        $disputes=$this->db->fetchAll("SELECT * FROM disputes WHERE order_id=:id ORDER BY id",['id'=>$orderId]);$dispute=count($disputes)===1?$disputes[0]:null;$refunds=$this->db->fetchAll("SELECT r.*,tf.id test_fact_id,tf.instance_id test_instance_id,tf.simulated_provider,p.app_id,p.mch_id,p.payer_openid,p.wechat_prepay_id,p.wechat_transaction_id FROM refunds r JOIN payment_orders p ON p.id=r.payment_order_id LEFT JOIN test_payment_facts tf ON tf.payment_order_id=p.id AND tf.instance_id=:instance WHERE r.order_id=:order_id ORDER BY r.id",['instance'=>$instanceId,'order_id'=>$orderId]);$refund=count($refunds)===1?$refunds[0]:null;$ledgers=$dispute?$this->db->fetchAll("SELECT * FROM worker_balance_ledger WHERE business_type='dispute' AND business_id=:dispute ORDER BY id",['dispute'=>(int)$dispute['id']]):[];$ledger=count($ledgers)===1?$ledgers[0]:null;$ownership=[];
